    # If there are fewer shards than jobs, each job gets one shard
    return [range(i, i+1) for i in range(num_shards)]
else:
    # If there are more shards than jobs, distribute shards evenly among jobs
    shards_per_job = num_shards // max_num_jobs
    extra_shards = num_shards % max_num_jobs
    shard_ranges = []

    for i in range(max_num_jobs):
        start = i * shards_per_job + min(i, extra_shards)
        end = start + shards_per_job + (i < extra_shards)
        shard_ranges.append(range(start, end))

    return shard_ranges

