    counters = {}

statuses = []
other = []

if isinstance(stderr, bytes):
    stderr = BytesIO(stderr)

for line in stderr:
    line = line.rstrip()

    m = _COUNTER_RE.match(line)
    if m:
        group, counter, amount = m.groups()
        counters.setdefault(group, {}).setdefault(counter, 0)
        counters[group][counter] += int(amount)
        continue

    m = _STATUS_RE.match(line)
    if m:
        statuses.append(m.group(1))
        continue

    other.append(line)

return {'counters': counters, 'statuses': statuses, 'other': other}

