def _in_date_range(log_file):
    return from_date <= log_file.timestamp() <= to_date

return pipe(self._valid_log_files(),
            filterz(_in_date_range),
            mapcatz(LogFile.records))

def _within_date_range(log_file):
    if log_file.timestamp() >= from_date and log_file.timestamp() <= to_date:
        return True
    return False

