tokens = list(reversed([t for t in parsed.tokens if not t.is_whitespace]))
keyword_idx = None
for i, token in enumerate(tokens[n_skip:]):
    if token.ttype is Token.Keyword:
        keyword_idx = i
        break
if keyword_idx is None:
