return None, sql

parsed = sqlparse.parse(sql)[0]
tokens = list(reversed([t for t in parsed.tokens if not t.is_whitespace]))

# Skip tokens
for _ in range(n_skip):
    if tokens:
        tokens.pop(0)

keyword_token = None
for token in tokens:
    if token.ttype in Token.Keyword:
        keyword_token = token
        break

if keyword_token is None:
    return None, sql

# Remove everything after the keyword
idx = sql.rfind(keyword_token.value)
return keyword_token.value, sql[:idx]

