s = s.replace("%", "~25")
parts = s.split("~")
decoded_parts = [parts[0]]
for part in parts[1:]:
    if part and len(part) >= 2:
        try:
            decoded_parts.append(chr(int(part[:2], 16)) + part[2:])
        except ValueError:
            decoded_parts.append("~" + part)
    else:
        decoded_parts.append("~" + part)
return "".join(decoded_parts).replace("~25", "%")

s = s.replace("%", "~p")
s = s.replace("+", " ")
parts = s.split("~")
for i in range(1, len(parts)):
    h = parts[i][0:2]
    if len(h) == 2 and h.isalnum():
        try:
            parts[i] = chr(int(h, 16)) + parts[i][2:]
        except ValueError:
            pass
s = "".join(parts)
return s.replace("~p", "%")

s = s.replace("%", "~TEMP~")
s = re.sub(r"~([0-9A-Fa-f]{2})", lambda m: chr(int(m.group(1), 16)), s)
return s.replace("~TEMP~", "%")

