if len(url) <= length:
    return url

# Check if the URL has a file extension
extension = url.split('.')[-1]
if len(extension) <= 4 and '/' not in extension:
    # Include the extension in the truncated URL
    truncated_length = length - len(extension) - 1 - 3  # for the ellipsis and the dot
    if truncated_length > 0:
        return url[:truncated_length] + '...' + '.' + extension
    else:
        # If there's not enough space for the main URL part, just return the ellipsis and extension
        return '...' + '.' + extension
else:
    # If there's no valid extension or not enough space, just truncate without worrying about the extension
    return url[:length - 3] + '...'

if len(url) <= length:
    return url

# Check if URL ends with a file extension
extension_match = re.search(r'\.[^./]{1,4}$', url)
if extension_match:
    extension = extension_match.group()
    base_length = length - len(extension) - 1  # for ellipsis
    if base_length > 0:
        return url[:base_length] + "…" + extension
    else:
        # Not enough space to include base part and ellipsis before extension
        return url[:length] + "…"
else:
    return url[:length-1] + "…"

if len(url) <= length:
    return url

# Check if the URL ends with a file extension
if '.' in url[-5:]:
    # Split the URL from the last dot to get the extension
    parts = url.rsplit('.', 1)
    base = parts[0]
    extension = parts[1]

    # If the URL is too long even without the extension
    if len(base) >= length - 1:
        return base[:length - 4] + '...' + extension
    else:
        # If adding the ellipsis and extension exceeds the length
        if len(base) + len(extension) + 1 > length:
            return base[:length - len(extension) - 4] + '...' + extension
        else:
            return base + '.' + extension
else:
    return url[:length - 3] + '...'

