if len(extension) <= 4 and '/' not in extension:
    # Calculate the length without the extension and the ellipsis
    length_without_extension = length - len(extension) - 4  # 3 for ellipsis, 1 for dot
    if length_without_extension > 0:
        return url[:length_without_extension] + "..." + "." + extension
    else:
        # If there's no room for the base URL, just return the ellipsis and extension
        return "..." + "." + extension
else:
    # If no extension or not applicable, just truncate and add ellipsis
    return url[:length-3] + "..."

