    # Calculate new length excluding the extension and ellipsis
    new_length = length - len(extension) - 3
    if new_length > 0:
        return url[:new_length] + "..." + extension
    else:
        # If there's not enough space for the extension and ellipsis,
        # just truncate to the length and add ellipsis
        return url[:length-3] + "..."
