# Check if array is 1D or 2D
if len(arr.shape) == 1:
    x = np.linspace(0, 1, len(arr))
    f = pchip(x, arr)
    x_new = np.linspace(0, 1, len(arr)*interp_val)
    return f(x_new)
elif len(arr.shape) == 2:
    x = np.linspace(0, 1, arr.shape[0])
    arr_new = np.zeros((arr.shape[0]*interp_val, arr.shape[1]))
    for i in range(arr.shape[1]):
        f = pchip(x, arr[:,i])
        x_new = np.linspace(0, 1, arr.shape[0]*interp_val)
        arr_new[:,i] = f(x_new)
    return arr_new
else:
    raise ValueError("Array must be 1D or 2D.")

