lines = []
for char in text:
    if char == '\n':  # Linefeed, move to a new line
        lines.append('')
    elif char == '\b':  # Backspace, remove the last character in the current line
        if lines and lines[-1]:  # Make sure there is a line and it's not empty
            lines[-1] = lines[-1][:-1]
    else:
        if not lines:  # If there are no lines, start a new one
            lines.append(char)
        else:
            lines[-1] += char  # Add character to the current line
return '\n'.join(lines)

